{"version":3,"file":"Dashboard.jsdbx","sources":["../../src/client/components/Dashboard.tsx"],"sourcesContent":["import React, { useState, useEffect } from "react";
import {
  NowRecordListConnected,
} from "@servicenow/react-components/NowRecordListConnected";

interface Props {
  onViewIncidents: () => void;
  onSelectIncident: (id: string) => void;
}

interface Metrics {
  totalOpen: number;
  criticalHigh: number;
  resolvedToday: number;
  slaAtRisk: number;
}

function MetricCard({ label, val, color }: { label: string; val: number | string; color: string }) {
  return (
    <div className="metric-card" style={{ borderTopColor: color }}>
      <div className="metric-value">{val}</div>
      <div className="metric-label">{label}</div>
    </div>
  );
}

export default function Dashboard({
  onViewIncidents,
  onSelectIncident,
}: Props) {
  const [metrics, setMetrics] = useState<Metrics | null>(null);

  useEffect(() => {
    const token = (window as any).g_ck || "";
    const hdrs: HeadersInit = { "X-UserToken": token, Accept: "application/json" };

    async function fetchCount(q: string): Promise<number> {
      try {
        const r = await fetch(
          `/api/now/stats/incident?sysparm_query=${encodeURIComponent(q)}&sysparm_count=true`,
          { headers: hdrs }
        );
        const d = await r.json();
        return parseInt(d?.result?.stats?.count ?? "0", 10) || 0;
      } catch {
        return 0;
      }
    }

    Promise.all([
      fetchCount("active=true"),
      fetchCount("active=true^priorityIN1,2"),
      fetchCount("state=6"),
      fetchCount("active=true^priority=1"),
    ]).then(([open, crit, resolved, p1]) =>
      setMetrics({ totalOpen: open, criticalHigh: crit, resolvedToday: resolved, slaAtRisk: p1 })
    );
  }, []);

  return (
    <div className="campus-app">
      <div className="campus-header">
        <h1 className="section-title">CampusDesk AI Dashboard</h1>
        <span className="nav-link" onClick={onViewIncidents} role="button" tabIndex={0}>
          View All Incidents &rarr;
        </span>
      </div>

      <div className="metrics-grid">
        <MetricCard label="Total Open" val={metrics ? metrics.totalOpen : "..."} color="#0080a3" />
        <MetricCard label="Critical / High" val={metrics ? metrics.criticalHigh : "..."} color="#c4314b" />
        <MetricCard label="Resolved" val={metrics ? metrics.resolvedToday : "..."} color="#2e8540" />
        <MetricCard label="P1 Active" val={metrics ? metrics.slaAtRisk : "..."} color="#e07c00" />
      </div>

      <h2 className="section-title" style={{ marginBottom: "0.5rem" }}>Recent Open Incidents</h2>
      <NowRecordListConnected
        key="active=true"
        table="incident"
        listTitle="Open Incidents"
        columns="number,short_description,priority,state,assigned_to"
        hideHeader={true}
        limit={10}
        onRowClicked={(e: any) =>
          onSelectIncident(e.detail.payload.sys_id)
        }
      />
    </div>
  );
}
